/** Root of a hierarchy: a branch carries children, a leaf carries a value. Never both. */
export type Data = { name: string; value?: number; children?: Data[] };

type Row = d3.HierarchyNode<Data>;

const MARGIN = { top: 28, right: 12, bottom: 10, left: 14 };
const ROW_HEIGHT = 18;
/** Horizontal step per depth level; the elbow's foot spans exactly one step. */
const INDENT = 14;
const DOT_RADIUS = 2.5;
const FONT_SIZE = 11;
/** Mean advance width of 11px sans-serif, used to drop names that would reach the value columns. */
const CHAR_WIDTH = 6.1;
const COUNT_COLUMN_WIDTH = 46;
const SIZE_COLUMN_WIDTH = 58;

const format = d3.format(',');

function leafCount(node: Row): number {
  return node.children ? d3.sum(node.children, leafCount) : 1;
}

function pathOf(node: Row): string {
  return node
    .ancestors()
    .map((a) => a.data.name)
    .reverse()
    .join('/');
}

export default function IndentedTree({
  data = projectTree,
  width
}: {
  data?: Data;
  width: number;
}) {
  const rows = useMemo(() => {
    const root = d3.hierarchy(data).sum((d) => d.value ?? 0);
    const ordered: Row[] = [];
    // Pre-order, because descendants() iterates breadth-first in d3 v7 and rows must read top-down.
    root.eachBefore((d) => ordered.push(d));
    return ordered;
  }, [data]);

  const indexOf = useMemo(() => {
    const map = new Map<Row, number>();
    rows.forEach((d, i) => map.set(d, i));
    return map;
  }, [rows]);

  const height = MARGIN.top + rows.length * ROW_HEIGHT + MARGIN.bottom;
  const innerWidth = width - MARGIN.left - MARGIN.right;
  const countColumnX = innerWidth;
  const sizeColumnX = innerWidth - COUNT_COLUMN_WIDTH;
  const nameLimit = sizeColumnX - SIZE_COLUMN_WIDTH;

  const yOf = (node: Row) => (indexOf.get(node) ?? 0) * ROW_HEIGHT + ROW_HEIGHT / 2;

  if (width === 0) return null;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Indented tree of a project file hierarchy with size and file count columns"
    >
      <g transform={`translate(${MARGIN.left},${MARGIN.top})`} fontSize={FONT_SIZE}>
        <g fill="var(--muted)" fontWeight={600}>
          <text x={sizeColumnX} y={-ROW_HEIGHT / 2} dy="0.32em" textAnchor="end">
            Size
          </text>
          <text x={countColumnX} y={-ROW_HEIGHT / 2} dy="0.32em" textAnchor="end">
            Count
          </text>
        </g>

        <g fill="none" stroke="var(--line)">
          {rows.flatMap((source) =>
            (source.children ?? []).map((target) => (
              <path
                key={pathOf(target)}
                d={`M${source.depth * INDENT},${yOf(source)}V${yOf(target)}h${INDENT}`}
              />
            ))
          )}
        </g>

        {rows.map((node) => {
          const y = yOf(node);
          const labelX = node.depth * INDENT + 6;
          const isLeaf = !node.children;
          const size = format(node.value ?? 0);
          const count = isLeaf ? '-' : format(leafCount(node));
          const fitsName = labelX + node.data.name.length * CHAR_WIDTH < nameLimit;

          return (
            <g key={pathOf(node)} transform={`translate(0,${y})`}>
              <title>{`${pathOf(node)}\n${size} bytes`}</title>
              <circle
                cx={node.depth * INDENT}
                r={DOT_RADIUS}
                fill={isLeaf ? 'var(--muted)' : 'var(--accent)'}
              />
              {fitsName && (
                <text x={labelX} dy="0.32em" fill="var(--text)">
                  {node.data.name}
                </text>
              )}
              <text x={sizeColumnX} dy="0.32em" textAnchor="end" fill="var(--muted)">
                {size}
              </text>
              <text x={countColumnX} dy="0.32em" textAnchor="end" fill="var(--muted)">
                {count}
              </text>
            </g>
          );
        })}
      </g>
    </svg>
  );
}
